export const TRICK_KEY = "knobbed_whelk";
export const TRICKS = ["siphonprobe", "footplow", "opercdoor", "knobbyrock", "whelkhaul", "canalprobe", "busyconhush"] as const;
export const HAPPY = ["densknurl", "inkknurl", "densbusycon"] as const;
export type KnobbedWhelkTrickKind = (typeof TRICKS)[number];
export type KnobbedWhelkHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type KnobbedWhelkTrick = {
  kind: KnobbedWhelkTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type KnobbedWhelkHappy = {
  kind: KnobbedWhelkHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { densknurl: 1.70, inkknurl: 1.84, densbusycon: 1.76 } as const;
export const BUSYCONHUSH_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  busyconhush: BUSYCONHUSH_HOLD + RELEASE_S,
  siphonprobe: 2.48,
  footplow: 2.42,
  opercdoor: 2.40,
  knobbyrock: 2.44,
  whelkhaul: 2.38,
  canalprobe: 2.56,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: KnobbedWhelkTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "busyconhush") return 40 + roll * 26;
  if (kind === "whelkhaul" || kind === "siphonprobe" || kind === "knobbyrock") return 12.8 + roll * 9.4;
  if (kind === "opercdoor" || kind === "footplow" || kind === "canalprobe") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}

